// BAD: Improper use of Java API leading to SQL Injection (vulnerable)
import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletBad extends HttpServlet {
    // JDBC details (for example purposes only)
    private static final String URL = "jdbc:postgresql://localhost:5432/appdb";
    private static final String USER = "appuser";
    private static final String PASS = "apppass";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username"); // user-controlled input
        String password = req.getParameter("password"); // user-controlled input

        // BAD: Direct string concatenation into a SQL query is vulnerable to SQL Injection
        String sql = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'"; // vulnerable

        try (Connection conn = DriverManager.getConnection(URL, USER, PASS);
             Statement stmt = conn.createStatement(); // misuse: using Statement with untrusted data
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                resp.getWriter().write("Login successful for user " + username);
            } else {
                resp.getWriter().write("Invalid credentials");
            }
        } catch (SQLException e) {
            // BAD: Leaking internal error details can disclose sensitive info
            resp.getWriter().write("Database error: " + e.getMessage());
        }
    }
}
***
/* GOOD: Proper use of PreparedStatement and safe error handling to prevent SQL Injection */
import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletGood extends HttpServlet {
    // JDBC details (for example purposes only)
    private static final String URL = "jdbc:postgresql://localhost:5432/appdb";
    private static final String USER = "appuser";
    private static final String PASS = "apppass";

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // GOOD: Use parameterized queries to avoid injection
        String sql = "SELECT id FROM users WHERE username = ? AND password = ?";

        // Optional: enforce basic input constraints before hitting DB (defense in depth)
        if (username == null || username.length() > 64 || password == null || password.length() > 128) {
            resp.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            resp.getWriter().write("Invalid input");
            return;
        }

        try (Connection conn = DriverManager.getConnection(URL, USER, PASS);
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, username);
            ps.setString(2, password); // In real apps, compare password hashes, not plaintext

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    resp.getWriter().write("Login successful for user " + username);
                } else {
                    // Do not reveal whether username or password is wrong
                    resp.getWriter().write("Invalid credentials");
                }
            }
        } catch (SQLException e) {
            // GOOD: Generic error message; do not leak internal details
            resp.setStatus(HttpServletResponse.SC_INTERNAL_SERVER_ERROR);
            resp.getWriter().write("An unexpected error occurred. Please try again later.");
            // Optionally log e securely on the server side (not returned to client)
        }
    }
}

