// BAD: Improper use of JDBC API leading to SQL Injection
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class VulnerableLoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String user = req.getParameter("username");
        String pass = req.getParameter("password");

        // vulnerable: concatenating user input directly into SQL
        String sql = "SELECT id FROM users WHERE username = '" + user + "' AND password = '" + pass + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:yourdb", "u", "p");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) { // Executes attacker-controlled SQL
            if (rs.next()) {
                // Auth success (but can be bypassed via injection)
            } else {
                // Auth failed
            }
        } catch (SQLException e) {
            // Log/handle error
        }
    }
}
