/**
 * GOOD: Safe use of JDBC API with PreparedStatement to prevent SQL Injection.
 * Also uses basic password hashing check in code (illustrative).
 */
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.security.MessageDigest;
import java.util.HexFormat;

public class SafeLoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String user = req.getParameter("username");
        String pass = req.getParameter("password");

        // Hash the password before comparison (illustrative; prefer a strong password hashing library like bcrypt/Argon2)
        String passHash = hashSha256(pass);

        String sql = "SELECT id FROM users WHERE username = ? AND password_hash = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:yourdb", "u", "p");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // Bind parameters instead of concatenating input
            ps.setString(1, user);
            ps.setString(2, passHash);

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // Auth success
                } else {
                    // Auth failed
                }
            }
        } catch (SQLException e) {
            // Log/handle error
        }
    }

    private static String hashSha256(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(md.digest(input.getBytes()));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}

